-- GAWR GURA SKY - iPad/Delta All-In-One V1
-- Uses the censored/non-explicit outdoor six-face sky from the supplied ZIP.
local env=(getgenv and getgenv()) or _G
local write=rawget(env,"writefile") or writefile
local custom=rawget(env,"getcustomasset") or getcustomasset or getsynasset
if not(write and custom)then warn("[GURA SKY] asset APIs unavailable")return end
local decode
pcall(function()if crypt and crypt.base64decode then decode=crypt.base64decode end end)
pcall(function()if not decode and crypt and crypt.base64 and crypt.base64.decode then decode=crypt.base64.decode end end)
pcall(function()if not decode and syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then decode=syn.crypt.base64.decode end end)
if not decode then warn("[GURA SKY] base64 decoder unavailable")return end
local DATA={
bk=[[]],
dn=[[]],
ft=[[]],
lf=[[]],
rt=[[]],
up=[[]],
}
local props={bk="SkyboxBk",dn="SkyboxDn",ft="SkyboxFt",lf="SkyboxLf",rt="SkyboxRt",up="SkyboxUp"}
local assets={}
for _,f in ipairs({"bk","dn","ft","lf","rt","up"})do
 local ok,a=pcall(function()local fn="gura_"..f..".tex";write(fn,decode(DATA[f]));return custom(fn)end)
 if ok then assets[f]=a else warn("[GURA SKY] "..f.." failed: "..tostring(a))end
 task.wait(.15)
end
local L=game:GetService("Lighting")
local function apply()
 local s=L:FindFirstChildOfClass("Sky")
 if not s then s=Instance.new("Sky");s.Name="GuraEmbeddedSky";s.Parent=L end
 for f,a in pairs(assets)do if a then pcall(function()s[props[f]]=a end)end end
end
apply()
L.ChildAdded:Connect(function(o)if o:IsA("Sky")then task.delay(.2,apply)end end)
task.spawn(function()for _,t in ipairs({.5,1.5,3,6,10})do task.wait(t);apply()end end)
pcall(function()game:GetService("StarterGui"):SetCore("SendNotification",{Title="Gawr Gura Sky",Text="Embedded six-face sky loaded",Duration=6})end)
